import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Give Feedback — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Give Feedback — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/feedback"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Give Feedback — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/feedback"}]]},"headers":[],"relativePath":"user-guide/feedback.md","filePath":"user-guide/feedback.md","lastUpdated":1787850471000}'),s={name:"user-guide/feedback.md"};function i(n,e,d,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="give-feedback-—-user-guide" tabindex="-1">Give Feedback — User Guide <a class="header-anchor" href="#give-feedback-—-user-guide" aria-label="Permalink to &quot;Give Feedback — User Guide&quot;">​</a></h1><p>Feedback is a <strong>platform</strong> capability, not a Marketplace module. Every signed-in workspace user can report a bug or suggest an improvement, and there is nothing to install or entitle.</p><p>Architecture and API contracts live in <a href="/developer-guide/central-feedback-system">Central Feedback System</a>.</p><h2 id="sending-feedback-workspace-users" tabindex="-1">Sending feedback (workspace users) <a class="header-anchor" href="#sending-feedback-workspace-users" aria-label="Permalink to &quot;Sending feedback (workspace users)&quot;">​</a></h2><p>Open the dialog from either place:</p><ul><li><strong>User menu</strong> (avatar, top right) → <strong>Give Feedback</strong></li><li><strong>Command palette</strong> (<code>Ctrl</code>/<code>⌘</code> + <code>K</code>) → <strong>Give Feedback</strong> under <strong>Actions</strong></li></ul><p>Then fill in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td>Type</td><td>Bug, Feature request, UX / Usability, Performance, Integration, Other</td></tr><tr><td>Title</td><td>Short summary, at least 3 characters</td></tr><tr><td>Description</td><td>At least 10 characters — what you did, what you expected, what happened</td></tr><tr><td>Module</td><td><strong>Required.</strong> Searchable list of installed modules; prefilled from the page you were on when possible. Choose <strong>Other</strong> when the report is not about a module — then <strong>What area?</strong> is required (for example Billing or login)</td></tr><tr><td>Impact</td><td>Optional — Low, Medium, High, Critical</td></tr><tr><td>Screenshot</td><td>Optional PNG, JPG, WebP, GIF, PDF, or text file up to 5 MB</td></tr></tbody></table><p>Submitting shows a confirmation toast with the reference number (for example <code>FB-000123</code>). Quote that number if you follow up.</p><h3 id="what-is-captured-automatically" tabindex="-1">What is captured automatically <a class="header-anchor" href="#what-is-captured-automatically" aria-label="Permalink to &quot;What is captured automatically&quot;">​</a></h3><p>So you do not have to describe your setup, the dialog also sends the page route and full URL you were on when you opened it, your browser user agent, and the app build version. The dialog tells you which page it captured before you submit.</p><h3 id="my-submissions-and-ticket-detail" tabindex="-1">My submissions and ticket detail <a class="header-anchor" href="#my-submissions-and-ticket-detail" aria-label="Permalink to &quot;My submissions and ticket detail&quot;">​</a></h3><p>The <strong>My submissions</strong> tab in the same dialog lists your recent reports with their current status (New, Triaged, Planned, In progress, Resolved, Closed, Duplicate, Won&#39;t fix, Not reproducible). It refreshes automatically after you send something new. Open a row to go to that ticket’s <strong>detail page</strong> (<code>/#/feedback/…</code>) — description, attachments, public replies, and a status/module history track. Only <strong>you</strong> can see your own submissions; other workspaces (and other people in your workspace) cannot.</p><p>When Central changes the status of your report or posts a <strong>Public response</strong>, you also receive an email at the address on your workspace account with the ticket number, title, and the update details. Status-change emails wait briefly so quick triage updates only notify for the final status. The email includes a link that opens that ticket’s detail page. Internal operator notes and triage priority are never shown to you or emailed.</p><p>Shared product ideation across tenants (vote / comment on sanitized feature ideas) is a future <strong>Feature Board</strong> — not this flow. See <a href="/getting-started/product-roadmap#parked-do-not-promise-wait-for-multi-tenant-signal">Product Roadmap</a>.</p><h2 id="triaging-feedback-central-operators" tabindex="-1">Triaging feedback (Central operators) <a class="header-anchor" href="#triaging-feedback-central-operators" aria-label="Permalink to &quot;Triaging feedback (Central operators)&quot;">​</a></h2><p>Central users work every workspace from one inbox at <strong>Platform → Feedback</strong>.</p><ul><li>Filter by type, status, and priority, or search across submissions</li><li>Stats chips summarize new items, open bugs, critical items, feature requests, work in progress, and what was resolved this week</li><li>Open a row to see the reporter, workspace, module and page context, description, and attachments</li><li>Set <strong>status</strong> and <strong>priority</strong>, then <strong>Save triage</strong></li><li>Add an <strong>Internal note</strong> (Central only) or a <strong>Public response</strong> (visible to the reporter)</li></ul><p>Status changes and public responses email the reporter automatically. Internal notes do not.</p><p><strong>Platform → Beta Applications</strong> lists Founding Beta signups from the marketing site, where operators record a status (New, Reviewed, Accepted, Rejected, Waitlisted) and private notes. See <a href="/product/founding-beta">Founding Beta</a>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Workspace users need <strong>no permission</strong> to submit feedback or read their own submissions. Central triage is gated by:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Ability</th></tr></thead><tbody><tr><td><code>feedback.list</code></td><td>See the Central Feedback inbox</td></tr><tr><td><code>feedback.read</code></td><td>Open a submission&#39;s full detail, including internal notes</td></tr><tr><td><code>feedback.update</code></td><td>Change status, priority, and module linkage</td></tr><tr><td><code>feedback.comment</code></td><td>Add internal notes and public responses</td></tr><tr><td><code>feedback.stats</code></td><td>See the triage summary chips</td></tr><tr><td><code>beta-applications.list</code> / <code>.read</code> / <code>.update</code></td><td>Review and annotate Founding Beta applications</td></tr></tbody></table>',23)])])}const g=t(s,[["render",i]]);export{h as __pageData,g as default};
